function disable_images_interaction(){let e=document.getElementsByTagName("img");for(let t=0;t<e.length;t++)e[t].style.pointerEvents="none"}function get_copyright(){let e=document.getElementById("copyright-year");let t=(new Date).getFullYear();e.innerHTML=t>2024?`© 2024-${t}`:`© ${t}`}function enable_tooltips(){[...document.querySelectorAll('[data-bs-toggle="tooltip"]')].map((e=>new bootstrap.Tooltip(e)))}function toggle_mode_initialize(){let e=localStorage.getItem("web-mode");null!==e?"light"!==e&&"dark"!==e||console.log("working"):localStorage.setItem("web-mode","light")}document.addEventListener("DOMContentLoaded",(e=>setInterval((()=>{let e=document.getElementById("pre-loader");e.classList.contains("hidden")||e.classList.add("hidden")}),1e3))),document.addEventListener("DOMContentLoaded",(e=>{disable_images_interaction()})),document.addEventListener("DOMContentLoaded",(e=>{enable_tooltips()})),document.addEventListener("DOMContentLoaded",(e=>{get_copyright()})),document.addEventListener("DOMContentLoaded",(e=>toggle_mode_initialize()));